import { describe, expect, it } from "vitest";
import * as XLSX from "xlsx";
import { MONTHLY_PREVIEW_LIMITS, parseMonthlyFinancialReportPreview as parse, MonthlyPreviewError } from "../shared/monthlyFinancialReportPreview";

// Manually specified ERP-style export and gold values, not generated by parser mappings.
const top = ["时间", "ASIN", "父ASIN", "店铺", "站点", "币种", "SKU", "品名", "毛利润", "销量", "销量", "订单收入", "订单收入", "退款量", "退货量", "退款", "推广费", "推广费", "推广费", "商品成本支出-采购成本(先进先出)", "商品成本支出-头程费用(先进先出)", "其余服务费", "其余服务费", "其他收入", "广告花费", "广告订单量", "广告销售额"];
const detail = ["时间", "ASIN", "父ASIN", "店铺", "站点", "币种", "SKU", "品名", "毛利润", "FBA销量", "FBM销量", "FBA销售额", "FBM销售额", "FBA退款量", "退货可售", "FBA销售额退款", "LD费", "优惠券", "Vine", "FBA采购成本", "FBA头程费用", "月仓储费报告", "月仓储费占比", "赔付", "SP", "SP广告订单量", "SP广告销售额"];
const sourceRow = ["202604", "B000000001", "B000000009", "店铺A", "美国", "USD", "sku01", "测试商品", "30.10", "10", "0", "100.10", "0.20", "2", "1", "-20.00", "-2", "-3", "1", "(20.00)", "-5", "-2", "0.02", "3", "-12", "3", "40"];
const flatTop = ["月份", "ASIN", "父ASIN", "店铺", "站点", "币种", "毛利润", "销量", "销售额", "退款量", "退货量"];
const flatRow = ["2026-04", "B000000001", "", "甲店", "加拿大", "CAD", "0.1", "2", "0.2", "0", "0"];
const enc = (value: string) => new TextEncoder().encode(value);
const quote = (value: unknown) => '"' + String(value ?? "").replace(/"/g, '""') + '"';
const csv = (rows: unknown[][]) => enc(rows.map(row => row.map(quote).join(",")).join("\r\n"));
function xlsx(rows: unknown[][], edit?: (sheet: XLSX.WorkSheet) => void, compressed = false): Uint8Array {
  const sheet = XLSX.utils.aoa_to_sheet(rows); edit?.(sheet);
  const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, sheet, "月报");
  return new Uint8Array(XLSX.write(book, { type: "array", bookType: "xlsx", compression: compressed }));
}
function xlsxFormulaXml(formulaXml: string, compressed = false, partName = "sheet1.xml"): Uint8Array {
  const original = xlsx([flatTop, flatRow], sheet => { sheet.G2 = { t: "n", v: 99, f: "1+1" }; });
  const archive = XLSX.CFB.read(Buffer.from(original), { type: "buffer" });
  const member = archive.FileIndex.find((file: { name: string }) => file.name === "sheet1.xml");
  const xml = Buffer.from(member.content).toString("utf8"); expect(xml).toContain("<f>1+1</f>");
  member.content = Buffer.from(xml.replace("<f>1+1</f>", formulaXml)); member.size = member.content.length;
  if (partName !== "sheet1.xml") {
    const index = archive.FileIndex.indexOf(member); member.name = partName;
    archive.FullPaths[index] = archive.FullPaths[index].replace("sheet1.xml", partName);
    for (const name of ["[Content_Types].xml", "workbook.xml.rels"]) {
      const related = archive.FileIndex.find((file: { name: string }) => file.name === name);
      const body = Buffer.from(related.content).toString("utf8"); expect(body).toContain("sheet1.xml");
      related.content = Buffer.from(body.replaceAll("sheet1.xml", partName)); related.size = related.content.length;
    }
  }
  return new Uint8Array(XLSX.CFB.write(archive, { type: "buffer", fileType: "zip", compression: compressed }));
}
const parseCsv = (rows: unknown[][]) => parse({ bytes: csv(rows), format: "csv" });
const rejection = (promise: ReturnType<typeof parse>, code: string) => expect(promise).rejects.toMatchObject({ name: "MonthlyPreviewError", code });

describe("monthly financial preview — human golden source", () => {
  it.each(["csv", "xlsx", "xlsx-compressed"])("retains signed source values and exact decimals: %s", async format => {
    const result = await parse(format === "csv" ? { bytes: csv([top, detail, sourceRow]), format: "csv" } : { bytes: xlsx([top, detail, sourceRow], undefined, format === "xlsx-compressed"), format: "xlsx" });
    const row = result.rows[0];
    expect(result.mode).toBe("memory-preview-only"); expect(result.amountConvention).toBe("source-signed-no-conversion");
    expect(row).toMatchObject({ yearMonth: "2026-04", asin: "B000000001", parentAsin: "B000000009", storeName: "店铺A", site: "美国", currency: "USD", rowNumber: 3 });
    for (const [field, value] of Object.entries({ financialProfit: "30.1", salesQty: "10", salesAmount: "100.3", refundAmount: "-20", refundQty: "2", returnQty: "1", promotion: "-4", ld: "-2", coupon: "-3", vine: "1", purchaseCost: "-20", freight: "-5", storage: "-2", otherIncome: "3", advertising: "-12", adOrders: "3", adSales: "40" })) {
      expect(row.metrics[field as keyof typeof row.metrics].value, field).toBe(value);
    }
    expect(row.metrics.otherFees).toEqual({ value: null, sources: [], unknownSources: [], absent: true });
    expect(row.ratios.profitMargin).toEqual({ numerator: "30.1", denominator: "100.3", fraction: "301/1003", reason: null });
    expect(row.ratios.refundRate.fraction).toBe("1/5");
    expect(row.cells[19]).toMatchObject({ address: "T3", value: "(20.00)" });
    expect(row.metrics.storage.sources).toEqual(["V3"]); // W3 is a reported percentage, not a fee.
  });
  it("adds exact denominators within one report scope, never averages ratios", async () => {
    const second = [...flatRow]; second[1] = "B000000002"; second[6] = "0.2"; second[7] = "8"; second[8] = "0.4"; second[9] = "2";
    const result = await parseCsv([flatTop, flatRow, second]);
    expect(result.summaries).toHaveLength(1);
    expect(result.summaries[0].metrics.financialProfit.value).toBe("0.3");
    expect(result.summaries[0].ratios.profitMargin).toEqual({ numerator: "0.3", denominator: "0.6", fraction: "1/2", reason: null });
    expect(result.summaries[0].ratios.refundRate).toEqual({ numerator: "2", denominator: "10", fraction: "1/5", reason: null });
  });
  it("keeps unallocated charges without allocating them to a child or inventing its parent", async () => {
    const fee = [...flatRow]; fee[1] = "-"; fee[2] = "--"; fee[6] = "-0.05"; fee[7] = "0"; fee[8] = "0";
    const result = await parseCsv([flatTop, flatRow, fee]);
    expect(result.rows[0].parentAsin).toBeNull(); expect(result.rows[1].allocation).toBe("unallocated");
    expect(result.rows[1].asin).toBeNull(); expect(result.rows[1].parentAsin).toBeNull();
    expect(result.summaries[0].allocation).toBe("report-scope-only-no-product-allocation");
    expect(result.summaries[0].metrics.financialProfit.value).toBe("0.05");
    expect(result.rows[0].metrics.financialProfit.value).toBe("0.1");
  });
  it("does not merge stores, sites or currencies and does not invent US/USD", async () => {
    const b = [...flatRow], c = [...flatRow], d = [...flatRow], unknown = [...flatRow];
    b[3] = "乙店"; c[4] = "美国"; d[5] = "USD"; unknown[5] = "";
    const result = await parseCsv([flatTop, flatRow, b, c, d, unknown]);
    expect(result.summaries).toHaveLength(4);
    expect(result.rows[4]).toMatchObject({ site: "加拿大", currency: null, currencySource: "unknown" });
    expect(result.excludedFromSummaries).toEqual([{ sheet: "CSV", rowNumber: 6, reason: "身份或币种不完整" }]);
    expect(result.rows[4].ratios.profitMargin.fraction).toBeNull();
  });
  it("preserves multiple parent candidates instead of assigning one", async () => {
    const row = [...flatRow]; row[2] = "B000000001,B000000009";
    const result = await parseCsv([flatTop, row]);
    expect(result.rows[0]).toMatchObject({ parentAsin: null, parentCandidates: ["B000000001", "B000000009"], allocation: "ambiguous" });
    expect(result.warnings.some(w => w.code === "IDENTITY_UNRESOLVED")).toBe(true);
  });
  it("retains a source total row and title containing 合计, without dropping real products", async () => {
    const row = [...sourceRow]; row[7] = "合计";
    const total = [...sourceRow]; total[0] = "总计"; total[1] = "";
    const result = await parseCsv([top, detail, row, total]);
    expect(result.rows.map(r => r.kind)).toEqual(["data", "summary"]);
    expect(result.summaries[0].sourceRows).toEqual([{ sheet: "CSV", rowNumber: 3 }]);
    expect(result.rows[1].cells[0].value).toBe("总计");
  });
  it.each(["小计", "Total", "Subtotal", "Grand Total"])("retains a %s identity row without counting the same report twice", async label => {
    const subtotal = [...flatRow]; subtotal[1] = label;
    const result = await parseCsv([flatTop, flatRow, subtotal]);
    expect(result.rows.map(row => row.kind)).toEqual(["data", "summary"]);
    expect(result.summaries[0].metrics.financialProfit.value).toBe("0.1");
    expect(result.rows[1].cells[1].value).toBe(label);
  });
});

describe("unknowns, identity and formula evidence", () => {
  it.each(["", "-", "--", "未知", "1,23", "1e3", "Infinity", "NaN", "12.345,67", "(-2)", "1.1234567890123"])("never coerces %j into zero", async value => {
    const row = [...flatRow]; row[6] = value;
    const result = await parseCsv([flatTop, row]);
    expect(result.rows[0].metrics.financialProfit.value).toBeNull(); expect(result.summaries[0].metrics.financialProfit.value).toBeNull();
    expect(result.rows[0].cells[6].value).toBe(value || null);
  });
  it.each([["0", "0"], ["-0.20", "-0.2"], ["$1,234.50", "1234.5"], ["(￥1,234.50)", "-1234.5"], ["12345678901234567890.12", "12345678901234567890.12"]])("preserves supported exact numeric string %s", async (input, output) => {
    const row = [...flatRow]; row[6] = input;
    expect((await parseCsv([flatTop, row])).rows[0].metrics.financialProfit.value).toBe(output);
  });
  it("keeps a formula's cached value as evidence, not a financial amount", async () => {
    const result = await parse({ bytes: xlsx([flatTop, flatRow], sheet => { sheet.G2 = { t: "n", v: 99, f: "1+1" }; }), format: "xlsx" });
    expect(result.rows[0].cells[6]).toMatchObject({ value: 99, formula: "1+1" });
    expect(result.rows[0].metrics.financialProfit.value).toBeNull();
    expect(result.warnings.some(w => w.code === "FORMULA_NOT_EVALUATED")).toBe(true);
  });
  it.each([
    '<f t="dataTable" ref="G2:G2" dt2D="0" r1="H2"/>',
    '<f t="dataTable" ref="G2:G2"></f>', '<f t="shared" si="999"/>',
    '<f t="shared" si="0" ref="G2:G3">1+1</f>', '<f t="array" ref="G2:G3">1+1</f>',
    "<f/>", "<f></f>", "<f> </f>", '<f t="normal" ref="G2:G3">1+1</f>',
  ])("refuses an unsupported/empty XML formula before a cached 99 can look like a source amount: %s", async formulaXml => {
    await rejection(parse({ bytes: xlsxFormulaXml(formulaXml), format: "xlsx" }), "XLSX_FORMULA_UNSUPPORTED");
  });
  it("checks formula XML inside compressed members and keeps supported ordinary formula evidence", async () => {
    await rejection(parse({ bytes: xlsxFormulaXml('<f t="dataTable" ref="G2:G2"/>', true), format: "xlsx" }), "XLSX_FORMULA_UNSUPPORTED");
    const result = await parse({ bytes: xlsxFormulaXml('<f t="normal" ca="1">1+1</f>', true), format: "xlsx" });
    expect(result.rows[0].cells[6]).toMatchObject({ value: 99, formula: "1+1" });
    expect(result.rows[0].metrics.financialProfit.value).toBeNull();
  });
  it.each(["sheet1.data", "sheet1.png", "sheet1.unknown"])("rejects unrecognized OPC parts instead of skipping formula checks: %s", async partName => {
    await rejection(parse({ bytes: xlsxFormulaXml('<f t="dataTable" ref="G2:G2"/>', false, partName), format: "xlsx" }), "XLSX_UNSUPPORTED");
  });
  it("scans .rels parts too if a workbook relationship points to one as a worksheet", async () => {
    await rejection(parse({ bytes: xlsxFormulaXml('<f t="dataTable" ref="G2:G2"/>', false, "sheet1.rels"), format: "xlsx" }), "XLSX_FORMULA_UNSUPPORTED");
  });
  it("refuses nonempty directory members even if named as worksheet targets", async () => {
    await rejection(parse({ bytes: xlsxFormulaXml('<f t="dataTable" ref="G2:G2"/>', false, "sheet1.xml/"), format: "xlsx" }), "XLSX_UNSUPPORTED");
  });
  it("does not evaluate a CSV formula, nor a formula used as identity", async () => {
    const row = [...flatRow]; row[0] = '=TEXT(A1,"YYYY-MM")'; row[6] = "=WEBSERVICE(\"https://example.invalid\")";
    const result = await parseCsv([flatTop, row]);
    expect(result.rows[0].yearMonth).toBeNull(); expect(result.rows[0].metrics.financialProfit.value).toBeNull();
    expect(result.summaries).toEqual([]);
  });
  it("propagates one missing component and a zero/negative denominator accurately", async () => {
    const row = [...sourceRow]; row[12] = ""; row[9] = "0";
    const result = await parseCsv([top, detail, row]);
    expect(result.rows[0].metrics.salesAmount).toMatchObject({ value: null, unknownSources: ["M3"] });
    expect(result.rows[0].ratios.refundRate).toMatchObject({ denominator: "0", fraction: null });
    row[9] = "-2"; row[12] = "0";
    expect((await parseCsv([top, detail, row])).rows[0].ratios.refundRate.fraction).toBeNull();
  });
  it("refuses conflicting currency arithmetic and accepts an explicit amount code without guessing a site", async () => {
    const row = [...sourceRow]; row[11] = "CAD 10";
    const result = await parseCsv([top, detail, row]);
    expect(result.rows[0].currency).toBeNull(); expect(result.rows[0].metrics.salesAmount.value).toBeNull();
    const onlyCode = [...flatRow]; onlyCode[5] = ""; onlyCode[6] = "CAD 0.1";
    expect((await parseCsv([flatTop, onlyCode])).rows[0]).toMatchObject({ currency: "CAD", currencySource: "amount-code", site: "加拿大" });
  });
  it("only mapped monetary columns contribute currency evidence, never metadata or counts", async () => {
    const row = [...flatRow]; row[3] = "USD 123"; row[7] = "USD 2";
    const result = await parseCsv([[...flatTop, "品名", "SKU", "未识别费"], [...row, "USD 123", "EUR 123", "GBP 9"]]);
    expect(result.rows[0]).toMatchObject({ storeName: "USD 123", title: "USD 123", sku: "EUR 123", currency: "CAD", currencySource: "column" });
    expect(result.rows[0].metrics.financialProfit.value).toBe("0.1");
    expect(result.rows[0].metrics.salesAmount.value).toBe("0.2");
    expect(result.rows[0].metrics.salesQty.value).toBeNull(); // Currency-coded counts are not quantities.
    expect(result.warnings.some(w => w.code === "CURRENCY_UNKNOWN")).toBe(false);
    row[5] = "";
    expect((await parseCsv([flatTop, row])).rows[0]).toMatchObject({ currency: null, currencySource: "unknown" });
  });
  it("does not use any of the four quantity metrics to infer currency", async () => {
    const row = [...sourceRow]; row[5] = "";
    for (const c of [9, 13, 14, 25]) row[c] = "USD 2";
    const result = await parseCsv([top, detail, row]);
    expect(result.rows[0].currency).toBeNull();
    for (const metric of ["salesQty", "refundQty", "returnQty", "adOrders"] as const) expect(result.rows[0].metrics[metric].value).toBeNull();
  });
  it("refuses duplicate complete identities, but retains incomplete identity rows", async () => {
    await rejection(parseCsv([flatTop, flatRow, flatRow]), "DUPLICATE_IDENTITY");
    const row = [...flatRow]; row[3] = ""; row[4] = ""; row[0] = "2026-13";
    const result = await parseCsv([flatTop, row]);
    expect(result.rows[0]).toMatchObject({ storeName: null, site: null, yearMonth: null }); expect(result.summaries).toEqual([]);
  });
  it("keeps unmapped fee columns and does not lose prototype-looking detail names", async () => {
    const detail2 = [...detail]; detail2[16] = "constructor";
    const result = await parseCsv([[...top, "神秘服务费"], [...detail2, "__proto__"], [...sourceRow, "-999"]]);
    expect(result.rows[0].cells.at(-1)?.value).toBe("-999");
    expect(result.warnings.find(w => w.code === "UNMAPPED_COLUMNS")?.columns).toEqual(["Q", "AB"]);
    expect(result.rows[0].metrics.promotion.value).toBeNull();
    expect(result.rows[0].metrics.promotion.unknownSources).toEqual(["Q3"]);
    expect(result.rows[0].cells[16].value).toBe("-2");
  });
});

describe("bounded headers, CSV and XLSX containers", () => {
  it("uses actual horizontal header merges, never arbitrary blank forward-fill", async () => {
    const headers = [...top]; headers[10] = ""; headers[12] = "";
    const bytes = xlsx([headers, detail, sourceRow], sheet => { sheet["!merges"] = [{ s: { r: 0, c: 9 }, e: { r: 0, c: 10 } }, { s: { r: 0, c: 11 }, e: { r: 0, c: 12 } }]; });
    expect((await parse({ bytes, format: "xlsx" })).rows[0].metrics.salesAmount.value).toBe("100.3");
    await rejection(parseCsv([headers, detail, sourceRow]), "HEADER_EMPTY");
  });
  it.each(["FBA销量", "LD费"])("does not mistake a flat first product named %s for a second header", async title => {
    const second = [...flatRow]; second[1] = "B000000002";
    const result = await parseCsv([[...flatTop, "品名"], [...flatRow, title], [...second, "普通商品"]]);
    expect(result.sheets[0].headerRows).toEqual([1]);
    expect(result.rows.map(row => [row.rowNumber, row.asin, row.title])).toEqual([[2, "B000000001", title], [3, "B000000002", "普通商品"]]);
  });
  it("rejects missing/duplicate columns and a total mixed with details", async () => {
    const headers = [...flatTop]; headers[2] = "未知";
    await rejection(parseCsv([headers, flatRow]), "HEADER_REQUIRED");
    headers[2] = "店铺"; await rejection(parseCsv([headers, flatRow]), "HEADER_DUPLICATE");
    const parts = [...detail]; parts[9] = "合计";
    await rejection(parseCsv([top, parts, sourceRow]), "HEADER_TOTAL_AMBIGUOUS");
  });
  it.each(["小计", "总销量", "总销售额", "总费用", "Total", "Subtotal", "Grand Total"])("rejects a %s subtotal mixed with FBA/FBM detail columns", async label => {
    await rejection(parseCsv([[...top, "销量"], [...detail, label], [...sourceRow, "10"]]), "HEADER_TOTAL_AMBIGUOUS");
  });
  it("handles UTF-8 BOM, embedded commas/newlines and escaped quotes without type coercion", async () => {
    const row = [...sourceRow]; row[7] = '名称,"原文"\n第二行'; row[6] = "0000123";
    const result = await parse({ bytes: enc("\uFEFF" + new TextDecoder().decode(csv([top, detail, row]))), format: "csv" });
    expect(result.rows[0].title).toBe(row[7]); expect(result.rows[0].sku).toBe("0000123");
  });
  it.each(['"broken', 'a"b', '"a"tail', "日期,ASIN,金额\n2026-01-01,B000000001,1"])("rejects invalid/unsupported CSV %s", async value => {
    await expect(parse({ bytes: enc(value), format: "csv" })).rejects.toBeInstanceOf(MonthlyPreviewError);
  });
  it("rejects empty/oversized files, invalid UTF-8, and excessive columns/rows before workbook reads", async () => {
    await rejection(parse({ bytes: new Uint8Array(), format: "csv" }), "EMPTY_FILE");
    await rejection(parse({ bytes: new Uint8Array(MONTHLY_PREVIEW_LIMITS.bytes + 1), format: "xlsx" }), "FILE_LIMIT");
    await rejection(parse({ bytes: new Uint8Array([0xff]), format: "csv" }), "CSV_ENCODING");
    await rejection(parse({ bytes: enc(",".repeat(256)), format: "csv" }), "SHEET_LIMIT");
    await rejection(parse({ bytes: enc("x\n".repeat(10001)), format: "csv" }), "SHEET_LIMIT");
    await rejection(parse({ bytes: enc("x".repeat(4097)), format: "csv" }), "CELL_LIMIT");
  });
  it("rejects oversized or sparse worksheet ranges instead of truncating", async () => {
    await rejection(parse({ bytes: xlsx([flatTop, flatRow], sheet => { sheet["!ref"] = "A1:K10001"; }), format: "xlsx" }), "SHEET_LIMIT");
    await rejection(parse({ bytes: xlsx([flatTop, flatRow], sheet => { sheet.IV10000 = { t: "s", v: "tail" }; sheet["!ref"] = "A1:IV10000"; }), format: "xlsx" }), "SHEET_LIMIT");
  });
  it("bounds the aggregate projected cells of multiple sparse sheets", async () => {
    const book = XLSX.utils.book_new();
    for (const name of ["一", "二"]) {
      const sheet = XLSX.utils.aoa_to_sheet([["notes"]]); sheet.J5001 = { t: "s", v: "tail" }; sheet["!ref"] = "A1:J5001";
      XLSX.utils.book_append_sheet(book, sheet, name);
    }
    await rejection(parse({ bytes: new Uint8Array(XLSX.write(book, { type: "array", bookType: "xlsx" })), format: "xlsx" }), "SHEET_LIMIT");
  });
  it("rejects formula headers/data merges and empty reports", async () => {
    await rejection(parse({ bytes: xlsx([flatTop, flatRow], sheet => { sheet.A1.f = '"月份"'; }), format: "xlsx" }), "HEADER_FORMULA");
    await rejection(parse({ bytes: xlsx([flatTop, flatRow], sheet => { sheet["!merges"] = [{ s: { r: 1, c: 0 }, e: { r: 2, c: 0 } }]; }), format: "xlsx" }), "DATA_MERGE");
    await rejection(parseCsv([flatTop]), "NO_DATA");
  });
  it("does not silently ignore unrelated sheets", async () => {
    const book = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([["notes"]]), "说明");
    XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([flatTop, flatRow]), "月报");
    const result = await parse({ bytes: new Uint8Array(XLSX.write(book, { type: "array", bookType: "xlsx" })), format: "xlsx" });
    expect(result.warnings).toContainEqual({ code: "UNRECOGNIZED_SHEET", message: "前 10 行未识别月报关键表头，该表不参与预览合计", sheet: "说明" });
  });
  it.each(["expanded", "entries", "encrypted", "zip64", "crc", "local-size", "overlap"])("rejects malicious ZIP metadata before spreadsheet interpretation: %s", async mode => {
    const bytes = xlsx([flatTop, flatRow]); const view = new DataView(bytes.buffer);
    const end = bytes.length - 22, central = view.getUint32(end + 16, true), local = view.getUint32(central + 42, true);
    if (mode === "expanded") view.setUint32(central + 24, MONTHLY_PREVIEW_LIMITS.expandedEntryBytes + 1, true);
    if (mode === "entries") { view.setUint16(end + 8, 257, true); view.setUint16(end + 10, 257, true); }
    if (mode === "encrypted") view.setUint16(central + 8, 1, true);
    if (mode === "zip64") view.setUint32(central + 24, 0xffffffff, true);
    if (mode === "crc") bytes[local + 30 + view.getUint16(local + 26, true) + view.getUint16(local + 28, true)] ^= 1;
    if (mode === "local-size") view.setUint32(local + 22, 1, true);
    if (mode === "overlap") {
      const firstLength = 46 + view.getUint16(central + 28, true) + view.getUint16(central + 30, true) + view.getUint16(central + 32, true);
      const second = central + firstLength;
      view.setUint32(second + 42, local, true); // At minimum overlaps an already-authenticated member.
    }
    await expect(parse({ bytes, format: "xlsx" })).rejects.toBeInstanceOf(MonthlyPreviewError);
  });
  it("rejects duplicate ZIP names even when their local names agree", async () => {
    const bytes = xlsx([flatTop, flatRow]), view = new DataView(bytes.buffer), end = bytes.length - 22;
    const byLength = new Map<number, number>(); let duplicated = false;
    for (let at = view.getUint32(end + 16, true); at < end;) {
      const length = view.getUint16(at + 28, true), first = byLength.get(length);
      if (first !== undefined) {
        const name = bytes.slice(first + 46, first + 46 + length), local = view.getUint32(at + 42, true);
        bytes.set(name, at + 46); bytes.set(name, local + 30); duplicated = true; break;
      }
      byLength.set(length, at); at += 46 + length + view.getUint16(at + 30, true) + view.getUint16(at + 32, true);
    }
    expect(duplicated).toBe(true);
    await rejection(parse({ bytes, format: "xlsx" }), "XLSX_ZIP");
  });
  it("rejects descriptor ZIPs before SheetJS can trust an oversized local allocation hint", async () => {
    const bytes = xlsx([flatTop, flatRow], undefined, true), view = new DataView(bytes.buffer), end = bytes.length - 22;
    const central = view.getUint32(end + 16, true), local = view.getUint32(central + 42, true);
    view.setUint16(central + 8, view.getUint16(central + 8, true) | 8, true);
    view.setUint16(local + 6, view.getUint16(local + 6, true) | 8, true);
    view.setUint32(local + 22, MONTHLY_PREVIEW_LIMITS.expandedEntryBytes + 1, true);
    await rejection(parse({ bytes, format: "xlsx" }), "XLSX_UNSUPPORTED");
  });
  it("checks actual decompression, not only a maliciously reduced expanded length", async () => {
    const bytes = xlsx([flatTop, flatRow], undefined, true), view = new DataView(bytes.buffer), end = bytes.length - 22;
    const central = view.getUint32(end + 16, true), local = view.getUint32(central + 42, true);
    view.setUint32(central + 24, 1, true); view.setUint32(local + 22, 1, true);
    await rejection(parse({ bytes, format: "xlsx" }), "XLSX_LIMIT");
  });
});
